import './Aibody.css';
import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import SpeechRecognition, { useSpeechRecognition } from 'react-speech-recognition';

const Aibody = () => {
    const [messages, setMessages] = useState([]); // State to store chat messages
    const [loading, setLoading] = useState(false); // State to show loading
    const [inputText, setInputText] = useState(""); // State to handle text input
    const { transcript, listening, resetTranscript } = useSpeechRecognition(); // Voice recognition hooks
    const textareaRef = useRef(null);
    const containerRef = useRef(null);
    const [isSpeechRecognitionSupported] = useState(SpeechRecognition.browserSupportsSpeechRecognition());

    // Load chat history from localStorage on component mount
    useEffect(() => {
        const savedChatHistory = JSON.parse(localStorage.getItem('chatHistory'));
        if (savedChatHistory) {
            setMessages(savedChatHistory);
        }
    }, []);

    // Save chat history to localStorage whenever it updates
    useEffect(() => {
        if (messages.length > 0) {
            localStorage.setItem('chatHistory', JSON.stringify(messages));
        }
    }, [messages]);

    if (!SpeechRecognition.browserSupportsSpeechRecognition()) {
        return <div>Your browser does not support speech recognition. Please use a modern browser.</div>;
    }

    // Handle toggle listening for voice input
    const handleToggleListening = async (e) => {

        e.preventDefault();

        if (!listening) {
            SpeechRecognition.startListening({ continuous: true });
        } else {
            SpeechRecognition.stopListening();
            const combinedInput = inputText || transcript; // Use either text input or transcript

            if (!combinedInput.trim()) {
                alert("Please say or type something before sending.");
                return;
            } else {
                await fetchApiResponse(combinedInput);
            }

            resetTranscript(); // Reset the transcript after stopping listening
        }
    };

    // Make an API call with the input (text or voice)
    const fetchApiResponse = async (input) => {
        setLoading(true);

        try {
            const response = await axios.post(`${process.env.REACT_APP_API_URL}/api/v1/search/QueryAnything`, {
                input,
                chatHistory: messages // Send previous chat history to the backend
            }, {
                headers: { 'Content-Type': 'application/json' }
            });
    
            if (response.data && response.data.chatHistory) {
                setMessages(response.data.chatHistory); // Update the chat history with the new response
            } else {
                console.error('Unexpected response structure:', response.data);
                setMessages((prevMessages) => [
                    ...prevMessages,
                    { role: 'user', content: input },
                    { role: 'assistant', content: 'Unexpected response format. Please try again.' }
                ]);
            }
        } catch (error) {
            console.error('Error fetching response from API:', error);
            setMessages((prevMessages) => [
                ...prevMessages,
                { role: 'user', content: input },
                { role: 'assistant', content: 'Error fetching response. Please try again.' }
            ]);
        } finally {
            setLoading(false); // Ensure loading state is reset
            setInputText(""); // Clear text input after submission
            resetTranscript(); // Reset transcript to ensure fresh input for next request
        }
    };

    // Handle text input submission
    const handleTextSubmit = async (e) => {
        e.preventDefault();
        const combinedInput = inputText || transcript; // Use either text input or transcript

        if (combinedInput.trim()) {
            await fetchApiResponse(combinedInput);
        } else {
            alert("Please enter or say something before submitting.");
        }

        resetTranscript(); // Clear the transcript after text submission
    };

    // Clear the chat and localStorage history
    const handleResetResponses = () => {
        setMessages([]);
        resetTranscript();
        setInputText("");
        localStorage.removeItem('chatHistory'); // Clear chat history from localStorage
    };
   
    useEffect(() => {
        const textarea = textareaRef.current;
        const container = containerRef.current;
        if (textarea && container) {
            const adjustContainerHeight = () => {
                if (textarea.scrollHeight > 48) {
                    container.style.height = `${Math.min(textarea.scrollHeight, 80)}px`;
                } else {
                    container.style.height = '3rem';
                }
            };
            textarea.addEventListener('input', adjustContainerHeight);
            return () => textarea.removeEventListener('input', adjustContainerHeight);
        }
    }, []);
    

    return (
     
      <div className="Contain">
        {!isSpeechRecognitionSupported ? (
                <div>Your browser does not support speech recognition. Please use a modern browser.</div>
            ) : (
                <>
        <div className="nav">
          <div className="nav3">
            <button
              className="resetbutn"
              onClick={handleResetResponses}
              style={{ padding: "0.5rem", fontSize: "0.9rem"}}
            >
              <i className="fa-solid fa-rotate" ></i>
            </button>
          </div>
          <div className="nav2">
            <h1>Chat AI</h1>
          </div>
          <div className="nav1">
            <img src="voice1.png" alt="" />
          </div>
        </div>

        {/* Display responses or loading state */}
        {loading ? (
          <div className="spinner"></div>
        ) : messages.length === 0 ? ( // Check if messages array is empty
          <div className="no-messages">
            <i class="fa-solid fa-microchip"></i>
            <p className="typewriter">
               Hello, How Can I Assist You 
            </p>
          </div> // Display "Hi" when there are no messages
        ) : (
          <div className="txtresponse">
            {messages.map((msg, index) => (
              <div
                key={index}
                className={
                  msg.role === "user" ? "user-message" : "assistant-message"
                }
              >
                <p>{msg.content}</p>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleTextSubmit}>
          <div className="respcontainer" ref={containerRef}>
            <div className="lis-butn">
              <button
                className="toggle-listen-btn"
                onClick={handleToggleListening}
                style={{ padding: "10px", fontSize: "16px" }}
                disabled={inputText.trim().length > 0}
              >
                {listening ? (
                  <i
                    class="fa-solid fa-microphone-slash"
                    style={{ fontSize: "1.5rem" }}
                  ></i>
                ) : (
                  <i
                    class="fa-solid fa-microphone"
                    style={{ fontSize: "1.5rem" }}
                  ></i>
                )}
              </button>
              {/* {listening && <p>Listening... Please speak now.</p>} */}
            </div>
            <div className="txtrequest">
              <textarea
                ref={textareaRef}
                value={inputText || transcript} // Show text input or transcript in the same box
                onChange={(e) => setInputText(e.target.value)} // Update text input state
                rows="4"
                cols="50"
                placeholder="Message.."
                disabled={listening} // Disable typing when listening
              />
            </div>

            <div className="buttnn">
              <button
                type="submit"
                className="startbutn1"
                disabled={listening || !inputText.trim()}
              >
                <i className="fa-solid fa-play"></i>
              </button>
            </div>
          </div>
        </form>
        </>
    )}
      </div>
    );
};

export default Aibody;
